wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::aap::caps::{http_client, notifier};
use crate::wasi::clocks::wall_clock;

struct Node;

impl Guest for Node {
    fn run(feed_url: String) -> HeartbeatReport {
        // Read the clock once; this is the reported instant.
        let seconds = wall_clock::now().seconds;

        // One permitted fetch. A transport failure is a value, so it is
        // reported as zero characters rather than failing the node.
        // An out-of-allowlist host traps at the boundary.
        let fetched = match http_client::fetch(&feed_url) {
            Ok(body) => u32::try_from(body.chars().count()).unwrap_or(u32::MAX),
            Err(_) => 0,
        };

        let message = format!("heartbeat at {seconds}: fetched {fetched} chars from {feed_url}");

        // ensures notified == true: the output may only be produced when the
        // notification was accepted. If it was refused, the node cannot
        // satisfy its contract, so it traps instead of returning notified = false.
        let accepted = notifier::notify(&message);
        if !accepted {
            panic!("notifier refused heartbeat; ensures notified == true cannot hold");
        }

        HeartbeatReport {
            seconds,
            fetched,
            notified: true,
        }
    }
}

export!(Node);
